static inline f32 HSD_CalcDeterminantMatrix3x4(Mtx m)
{
    f32 det = m[2][0] * (m[0][1] * m[1][2]);
    det = PF_SlippiMulAddF32(m[2][2], m[0][0] * m[1][1], det);
    det = PF_SlippiMulAddF32(m[2][1], m[0][2] * m[1][0], det);
    det = -PF_SlippiMulAddF32(m[0][2], m[2][0] * m[1][1], -det);
    det = -PF_SlippiMulAddF32(m[2][2], m[1][0] * m[0][1], -det);
    return -PF_SlippiMulAddF32(m[1][2], m[0][0] * m[2][1], -det);
}

void HSD_MtxInverse(Mtx src, Mtx dest)
{
    Mtx tempMatrix;
    Mtx* m;
    f32 det = HSD_CalcDeterminantMatrix3x4(src);

    if (fabsf_bitwise(det) < EPSILON) {
        MTXIdentity(dest);
        return;
    }

    if (src == dest) {
        MTXCopy(src, tempMatrix);
        m = &tempMatrix;
    } else {
        m = (Mtx*) src;
    }

    det = 1.0f / det;

    dest[0][0] = PF_SlippiMulAddF32((*m)[1][1], (*m)[2][2], -((*m)[2][1] * (*m)[1][2])) * det;
    dest[0][1] = -PF_SlippiMulAddF32((*m)[0][1], (*m)[2][2], -((*m)[2][1] * (*m)[0][2])) * det;
    dest[0][2] = PF_SlippiMulAddF32((*m)[0][1], (*m)[1][2], -((*m)[1][1] * (*m)[0][2])) * det;
    dest[1][0] = -PF_SlippiMulAddF32((*m)[1][0], (*m)[2][2], -((*m)[2][0] * (*m)[1][2])) * det;
    dest[1][1] = PF_SlippiMulAddF32((*m)[0][0], (*m)[2][2], -((*m)[2][0] * (*m)[0][2])) * det;
    dest[1][2] = -PF_SlippiMulAddF32((*m)[0][0], (*m)[1][2], -((*m)[1][0] * (*m)[0][2])) * det;
    dest[2][0] = PF_SlippiMulAddF32((*m)[1][0], (*m)[2][1], -((*m)[2][0] * (*m)[1][1])) * det;
    dest[2][1] = -PF_SlippiMulAddF32((*m)[0][0], (*m)[2][1], -((*m)[2][0] * (*m)[0][1])) * det;
    dest[2][2] = PF_SlippiMulAddF32((*m)[0][0], (*m)[1][1], -((*m)[1][0] * (*m)[0][1])) * det;

    dest[0][3] = -PF_SlippiMulAddF32(dest[0][2], src[2][3], -PF_SlippiMulAddF32(-dest[0][0], src[0][3], -(dest[0][1] * src[1][3])));
    dest[1][3] = -PF_SlippiMulAddF32(dest[1][2], src[2][3], -PF_SlippiMulAddF32(-dest[1][0], src[0][3], -(dest[1][1] * src[1][3])));
    dest[2][3] = -PF_SlippiMulAddF32(dest[2][2], src[2][3], -PF_SlippiMulAddF32(-dest[2][0], src[0][3], -(dest[2][1] * src[1][3])));
}

void HSD_MtxInverseTranspose(Mtx src, Mtx dest)
{
    Mtx* m;
    Mtx tempMatrix;
    f32 det = HSD_CalcDeterminantMatrix3x4(src);

    m = (Mtx*) src;

    if (fabsf_bitwise(det) < EPSILON) {
        if (*m != dest) {
            MTXCopy(*m, dest);
        }
    } else {
        if (*m == dest) {
            MTXCopy(*m, tempMatrix);
            m = &tempMatrix;
        }

        det = 1.0f / det;

        // This needs to be in a different order than in HSD_MtxInverse for
        // some reason
        dest[0][0] = PF_SlippiMulAddF32((*m)[1][1], (*m)[2][2], -((*m)[2][1] * (*m)[1][2])) * det;
        dest[1][0] = -PF_SlippiMulAddF32((*m)[0][1], (*m)[2][2], -((*m)[2][1] * (*m)[0][2])) * det;
        dest[2][0] = PF_SlippiMulAddF32((*m)[0][1], (*m)[1][2], -((*m)[1][1] * (*m)[0][2])) * det;
        dest[0][1] = -PF_SlippiMulAddF32((*m)[1][0], (*m)[2][2], -((*m)[2][0] * (*m)[1][2])) * det;
        dest[1][1] = PF_SlippiMulAddF32((*m)[0][0], (*m)[2][2], -((*m)[2][0] * (*m)[0][2])) * det;
        dest[2][1] = -PF_SlippiMulAddF32((*m)[0][0], (*m)[1][2], -((*m)[1][0] * (*m)[0][2])) * det;
        dest[0][2] = PF_SlippiMulAddF32((*m)[1][0], (*m)[2][1], -((*m)[2][0] * (*m)[1][1])) * det;
        dest[1][2] = -PF_SlippiMulAddF32((*m)[0][0], (*m)[2][1], -((*m)[2][0] * (*m)[0][1])) * det;
        dest[2][2] = PF_SlippiMulAddF32((*m)[0][0], (*m)[1][1], -((*m)[1][0] * (*m)[0][1])) * det;
        dest[0][3] = 0;
        dest[1][3] = 0;
        dest[2][3] = 0;
    }
}

